import serial
import time
import sys
import atexit

def read_and_validate_data(serial_port):
    try:
        # Read a line from the serial port
        data = serial_port.readline()
        if not data:
            return None
        # Decode the data and strip whitespace
        data_str = data.decode('utf-8').strip()
        # Simple validity check: must be a numeric value
        if data_str.isdigit():
            return int(data_str)
        else:
            print(f"Invalid data received: {data_str}")
            return None
    except Exception as e:
        print(f"Error reading or validating data: {e}")
        return None

def setup_serial(port='/dev/ttyS0', baudrate=9600, timeout=1):
    try:
        serial_port = serial.Serial(port, baudrate=baudrate, timeout=timeout)
        print(f"Serial port {port} opened successfully.")
        return serial_port
    except serial.SerialException as e:
        print(f"Failed to open serial port {port}: {e}")
        sys.exit(1)

def cleanup_serial(serial_port):
    if serial_port and serial_port.is_open:
        serial_port.close()
        print("Serial port closed.")

def main():
    # Setup serial communication
    serial_port = setup_serial()

    # Register cleanup function
    atexit.register(cleanup_serial, serial_port)

    # Attempt to read a valid data once
    reading = read_and_validate_data(serial_port)
    if reading is not None:
        print(f"Valid reading received: {reading}")
    else:
        print("No valid reading received. Exiting.")

