import os
import time
import signal
import logging
from picamera2 import Picamera2
from gpiozero import Device, DigitalOutputDevice
from contextlib import contextmanager

# Set up logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
CAMERA_SAVE_DIR = "/home/pi/camera_images"
IMAGE_FORMAT = "jpg"
IMAGE_QUALITY = 85
INTERVAL = 0.1
MAX_RETRIES = 3
RETRY_DELAY = 1

# Initialize camera
picam2 = None

# Initialize GPIO (example for a simple LED indicator)
led = DigitalOutputDevice(17, initial_value=False)

@contextmanager
def camera_context():
    global picam2
    try:
        picam2 = Picamera2()
        config = picam2.create_still_CAPTURE()
        picam2.configure(config)
        yield picam2
    except Exception as e:
        logging.error(f"Failed to initialize camera: {e}")
        raise
    finally:
        if picam2:
            picam2.close()
            picam2 = None

def setup_directories():
    if not os.path.exists(CAMERA_SAVE_DIR):
        try:
            os.makedirs(CAMERA_SAVE_DIR, exist_ok=True)
            logging.info(f"Created directory: {CAMERA_SAVE_DIR}")
        except Exception as e:
            logging.error(f"Failed to create directory: {e}")
            raise

def capture_image():
    global picam2
    if not picam2:
        raise RuntimeError("Camera not initialized")
    try:
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        filename = os.path.join(CAMERA_SAVE_DIR, f"image_{timestamp}.{IMAGE_FORMAT}")
        picam2.capture_file(filename)
        logging.info(f"Image saved to: {filename}")
        return True
    except Exception as e:
        logging.error(f"Failed to capture image: {e}")
        return False

def check_image_validity(filename):
    if not os.path.exists(filename):
        logging.error(f"Image file not found: {filename}")
        return False
    if not os.path.isfile(filename):
        logging.error(f"Invalid file type: {filename}")
        return False
    if os.path.getsize(filename) == 0:
        logging.error(f"Image file is empty: {filename}")
        return False
    return True

def signal_handler(sig, frame):
    logging.info("Received signal, shutting down...")
    try:
        if picam2:
            picam2.close()
        led.off()
    except Exception as e:
        logging.error(f"Error during shutdown: {e}")
    exit(1)

def main():
    setup_directories()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with camera_context():
            led.on()
            while True:
                try:
                    if capture_image():
                        time.sleep(INTERVAL)
                    else:
                        time.sleep(RETRY_DELAY)
                except Exception as e:
                    logging.error(f"Error during capture loop: {e}")
                    time.sleep(RETRY_DELAY)
    except Exception as e:
        logging.error(f"Main loop error: {e}")
    finally:
        if picam2:
            picam2.close()
        led.off()

if __name__ == "__main__":
    try:
        main()
    except Exception as e:
        logging.error(f"Program terminated with error: {e}")
        exit(1)

