import sys
import time
from gpiozero import Device, DeviceError
from gpiozero.pins.pigpio import PiGPIOFactory
from adafruit_pca9685 import PCA9685
from signal import signal, SIGINT, SIGTERM

# Set up the PCA9685 using gpiozero's PiGPIOFactory
pin_factory = PiGPIOFactory()

def setup_pca9685(i2c_address=0x40):
    try:
        pca = PCA9685(i2c_address, pin_factory=pin_factory)
        pca.frequency = 60
        return pca
    except DeviceError as e:
        print(f"Error initializing PCA9685 at address 0x{i2c_address:x}: {e}")
        sys.exit(1)

def read_pwm_value(pca, channel):
    try:
        value = pca.channels[channel].value
        if not (0 <= value <= 4095):
            raise ValueError(f"Invalid PWM value: {value}")
        return value
    except DeviceError as e:
        print(f"Error reading PWM value from channel {channel}: {e}")
        sys.exit(1)

def signal_handler(sig, frame):
    print("\nCleaning up and exiting...")
    pca.close()
    sys.exit(0)

def main():
    signal(SIGINT, signal_handler)
    signal(SIGTERM, signal_handler)

    pca = setup_pca9685()

    try:
        while True:
            for channel in range(16):
                value = read_pwm_value(pca, channel)
                print(f"Channel {channel}: {value}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("\nInterrupt received, cleaning up...")
    finally:
        pca.close()
        sys.exit(0)

if __name__ == "__main__":
    main()

import serial
import time
import sys
import signal

# Configuration
SERIAL_PORT = '/dev/ttyAMA0'  # Adjust based on your Raspberry Pi model
BAUD_RATE = 9600
RETRY_DELAY = 1  # seconds
MAX_RETRIES = 5
READ_INTERVAL = 0.1  # seconds

# Global flag to control exit
exit_flag = False

def signal_handler(sig, frame):
    global exit_flag
    print("\nInterrupt received. Cleaning up...")
    exit_flag = True

def setup_serial():
    for _ in range(MAX_RETRIES):
        try:
            ser = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
            if ser.is_open:
                print(f"Serial port {SERIAL_PORT} opened successfully.")
                return ser
        except serial.SerialException as e:
            print(f"Error opening serial port: {e}")
            time.sleep(RETRY_DELAY)
    print("Failed to open serial port after multiple attempts.")
    sys.exit(1)

def read_from_device(ser):
    try:
        if ser.in_waiting > 0:
            data = ser.readline().decode('utf-8').strip()
            print(f"Received: {data}")
            return data
        return None
    except serial.SerialException as e:
        print(f"Serial error: {e}")
        return None

def main():
    global exit_flag
    ser = setup_serial()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        while not exit_flag:
            data = read_from_device(ser)
            if data is None:
                print("No data received. Retrying...")
                time.sleep(READ_INTERVAL)
            else:
                time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nKeyboard interrupt received. Cleaning up...")
    finally:
        try:
            if 'ser' in locals() and ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        sys.exit(0 if exit_flag else 1)

if __name__ == "__main__":
    main()

